import{_ as s,C as o,o as e,c as p,a6 as a,E as i}from"./chunks/framework.BIQm0xy3.js";const m=JSON.parse('{"title":"Lab tuần 3. Nền tảng C++ trước khi vào lớp và đối tượng","description":"","frontmatter":{"title":"Lab tuần 3. Nền tảng C++ trước khi vào lớp và đối tượng"},"headers":[],"relativePath":"lab-tuan-3.md","filePath":"lab-tuan-3.md"}'),h={name:"lab-tuan-3.md"};function c(l,n,d,g,r,u){const t=o("DongHo");return e(),p("div",null,[n[0]||(n[0]=a('<p class="eyebrow">Bài lab · Tuần 3</p><h1 id="tuan-3-—-nen-tang-c-truoc-khi-vao-lop-va-đoi-tuong" tabindex="-1">Tuần 3 — Nền tảng C++ trước khi vào lớp và đối tượng <a class="header-anchor" href="#tuan-3-—-nen-tang-c-truoc-khi-vao-lop-va-đoi-tuong" aria-label="Permalink to &quot;Tuần 3 — Nền tảng C++ trước khi vào lớp và đối tượng&quot;">​</a></h1><blockquote><p><strong>Hệ thống xuyên suốt học kỳ: THƯ VIỆN.</strong> Từ tuần này đến tuần 10 chúng ta xây một hệ thống mượn trả thư viện. Mỗi tuần thêm một phần vào <strong>chính code của bạn</strong>, không làm lại từ đầu. Giữ kỹ thư mục bài làm mỗi tuần.</p><p>Tuần này chưa có lớp và đối tượng. Ta làm quen với dữ liệu của thư viện ở dạng thô: tên bạn đọc, số lượt mượn, số trang, mã tài liệu.</p></blockquote><h2 id="quy-uoc-ap-dung-cho-ca-hoc-ky" tabindex="-1">Quy ước áp dụng cho cả học kỳ <a class="header-anchor" href="#quy-uoc-ap-dung-cho-ca-hoc-ky" aria-label="Permalink to &quot;Quy ước áp dụng cho cả học kỳ&quot;">​</a></h2><ol><li><strong>Output không dấu tiếng Việt.</strong> <code>Da cho muon</code>, không phải <code>Đã cho mượn</code>. Console Windows hay vỡ font và bạn sẽ mất thời gian vô ích trong phòng thi.</li><li>Biên dịch bằng dòng lệnh, không bấm nút IDE:<div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">g++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -std=c++17</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Wall</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.exe</span></span></code></pre></div></li><li><strong>Nộp bài trước khi xem đáp án.</strong> Đáp án trên Moodle chỉ mở sau khi bạn đã nộp. Nộp bài chưa chạy được vẫn được tính — mục đích là bạn phải tự làm trước đã.</li></ol><hr><h2 id="bai-3-1-—-the-ban-đoc-10-phut" tabindex="-1">Bài 3.1 — Thẻ bạn đọc (10 phút) <a class="header-anchor" href="#bai-3-1-—-the-ban-đoc-10-phut" aria-label="Permalink to &quot;Bài 3.1 — Thẻ bạn đọc (10 phút)&quot;">​</a></h2>',7)),i(t,{khoa:"lab-3-1",phut:10}),n[1]||(n[1]=a(`<p>Nhập họ tên bạn đọc, in ra thẻ mượn.</p><p><strong>Yêu cầu:</strong> dùng <code>getline</code> để nhận cả họ và tên có khoảng trắng.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Nhap ho ten ban doc: Nguyen Van An</span></span>
<span class="line"><span>--- THE MUON THU VIEN ---</span></span>
<span class="line"><span>Chao Nguyen Van An, the cua ban da san sang!</span></span></code></pre></div><hr><h2 id="bai-3-2-—-đoan-ma-tai-lieu-20-phut" tabindex="-1">Bài 3.2 — Đoán mã tài liệu (20 phút) <a class="header-anchor" href="#bai-3-2-—-đoan-ma-tai-lieu-20-phut" aria-label="Permalink to &quot;Bài 3.2 — Đoán mã tài liệu (20 phút)&quot;">​</a></h2>`,5)),i(t,{khoa:"lab-3-2",phut:20}),n[2]||(n[2]=a(`<p>Hệ thống giữ một mã tài liệu ngẫu nhiên từ 1 đến 100. Người dùng đoán cho tới khi đúng.</p><p><strong>Yêu cầu:</strong></p><ul><li>Đoán nhỏ hơn → in <code>Ma that lon hon so do.</code></li><li>Đoán lớn hơn → in <code>Ma that nho hon so do.</code></li><li>Đoán đúng → in <code>Chinh xac! Ban tim ra sau &lt;n&gt; lan doan.</code></li><li>Đếm số lần đoán.</li></ul><p><strong>Gợi ý:</strong> <code>srand((unsigned) time(NULL));</code> rồi <code>rand() % 100 + 1</code>. Dùng <code>do ... while</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>He thong dang giu 1 ma tai lieu tu 1 den 100. Ban doan thu?</span></span>
<span class="line"><span>Ma ban doan: 50</span></span>
<span class="line"><span>Ma that nho hon so do.</span></span>
<span class="line"><span>Ma ban doan: 25</span></span>
<span class="line"><span>Ma that lon hon so do.</span></span>
<span class="line"><span>Ma ban doan: 37</span></span>
<span class="line"><span>Chinh xac! Ban tim ra sau 3 lan doan.</span></span></code></pre></div><hr><h2 id="bai-3-3-—-thong-ke-luot-muon-bang-ham-20-phut" tabindex="-1">Bài 3.3 — Thống kê lượt mượn bằng hàm (20 phút) <a class="header-anchor" href="#bai-3-3-—-thong-ke-luot-muon-bang-ham-20-phut" aria-label="Permalink to &quot;Bài 3.3 — Thống kê lượt mượn bằng hàm (20 phút)&quot;">​</a></h2>`,7)),i(t,{khoa:"lab-3-3",phut:20}),n[3]||(n[3]=a(`<p>Nhập số ngày <code>n</code>, nhập số lượt mượn từng ngày, cộng dồn <strong>qua một hàm riêng</strong>.</p><p><strong>Yêu cầu bắt buộc:</strong> phải có hàm <code>int themLuot(int tong, int them);</code> khai báo trước <code>main</code>, định nghĩa sau <code>main</code>. Không được cộng thẳng trong <code>main</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>So ngay can thong ke: 3</span></span>
<span class="line"><span>Nhap so luot muon moi ngay: 5 8 6</span></span>
<span class="line"><span>Tong so luot muon: 19</span></span></code></pre></div><hr><h2 id="bai-3-4-—-con-tro-va-mang-đong-20-phut" tabindex="-1">Bài 3.4 — Con trỏ và mảng động (20 phút) <a class="header-anchor" href="#bai-3-4-—-con-tro-va-mang-đong-20-phut" aria-label="Permalink to &quot;Bài 3.4 — Con trỏ và mảng động (20 phút)&quot;">​</a></h2>`,5)),i(t,{khoa:"lab-3-4",phut:20}),n[4]||(n[4]=a(`<p>Nhập số cuốn sách <code>n</code>, <strong>cấp phát động</strong> mảng <code>int</code> gồm <code>n</code> phần tử để chứa số trang, tính tổng số trang bằng hàm <code>int tongTrang(int* a, int n);</code>.</p><p><strong>Yêu cầu bắt buộc:</strong></p><ul><li>Cấp phát bằng <code>new int[n]</code>, giải phóng bằng <code>delete[]</code>.</li><li>Bên trong <code>tongTrang</code> phải truy cập bằng con trỏ: <code>*(a + i)</code>, không dùng <code>a[i]</code>.</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>So cuon sach: 3</span></span>
<span class="line"><span>Nhap so trang tung cuon: 350 220 480</span></span>
<span class="line"><span>Tong so trang la 1050</span></span></code></pre></div><hr><h2 id="bai-3-5-—-sap-xep-ma-tai-lieu-hoan-đoi-bang-con-tro-20-phut" tabindex="-1">Bài 3.5 — Sắp xếp mã tài liệu, hoán đổi bằng con trỏ (20 phút) <a class="header-anchor" href="#bai-3-5-—-sap-xep-ma-tai-lieu-hoan-đoi-bang-con-tro-20-phut" aria-label="Permalink to &quot;Bài 3.5 — Sắp xếp mã tài liệu, hoán đổi bằng con trỏ (20 phút)&quot;">​</a></h2>`,6)),i(t,{khoa:"lab-3-5",phut:20}),n[5]||(n[5]=a(`<p>Sắp xếp tăng dần mảng mã tài liệu bằng Bubble Sort.</p><p><strong>Yêu cầu bắt buộc:</strong> phải có hàm <code>void hoanDoi(int* a, int* b);</code> và Bubble Sort <strong>phải gọi hàm này</strong>.</p><blockquote><p>⚠️ <strong>Chỗ hay sai nhất của bài này.</strong> Nếu bạn viết <code>hoanDoi(ma[j], ma[j+1])</code> thì <code>ma[j]</code> là một <code>int</code>, không phải <code>int*</code>. Trình biên dịch sẽ <strong>không</strong> gọi hàm bạn vừa viết — nó lặng lẽ gọi <code>std::swap</code> của thư viện chuẩn (vì có <code>using namespace std;</code>). Chương trình vẫn sắp xếp đúng, còn hàm con trỏ của bạn thì không bao giờ chạy — tức là cả bài tập này trở thành vô nghĩa.</p><p>Phải truyền <strong>địa chỉ</strong>: <code>hoanDoi(&amp;ma[j], &amp;ma[j + 1]);</code></p><p>Cách tự kiểm tra: thêm <code>cout &lt;&lt; &quot;hoanDoi duoc goi&quot; &lt;&lt; endl;</code> vào đầu hàm. Nếu chạy chương trình mà không thấy dòng đó in ra lần nào, bạn đang mắc đúng lỗi này.</p></blockquote><p>Dữ liệu để thử: <code>{305, 118, 947, 220, 116, 673}</code></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Truoc khi sap xep: 305 118 947 220 116 673</span></span>
<span class="line"><span>Sau khi sap xep  : 116 118 220 305 673 947</span></span></code></pre></div><hr><h2 id="bai-3-6-—-tim-kiem-nhi-phan-25-phut" tabindex="-1">Bài 3.6 — Tìm kiếm nhị phân (25 phút) <a class="header-anchor" href="#bai-3-6-—-tim-kiem-nhi-phan-25-phut" aria-label="Permalink to &quot;Bài 3.6 — Tìm kiếm nhị phân (25 phút)&quot;">​</a></h2>`,7)),i(t,{khoa:"lab-3-6",phut:25}),n[6]||(n[6]=a(`<p>Dùng <strong>kết quả đã sắp xếp của bài 3.5</strong> làm dữ liệu vào. Nhập một mã, tìm bằng tìm kiếm nhị phân, trả về vị trí hoặc <code>-1</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ma tai lieu can tim: 305</span></span>
<span class="line"><span>Tim thay ma 305 o vi tri 3</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ma tai lieu can tim: 400</span></span>
<span class="line"><span>Khong co ma 400 trong kho.</span></span></code></pre></div><blockquote><p>Bài 3.5 → 3.6 là mắt xích đầu tiên của học kỳ: đầu ra của bài trước là đầu vào của bài sau. Từ tuần 4 trở đi mọi tuần đều như vậy.</p></blockquote><hr><h2 id="file-phai-nop" tabindex="-1">File phải nộp <a class="header-anchor" href="#file-phai-nop" aria-label="Permalink to &quot;File phải nộp&quot;">​</a></h2><p>Sáu file <code>.cpp</code> riêng, đặt tên đúng:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;MSSV&gt;_w03/</span></span>
<span class="line"><span>  3_1_the_ban_doc.cpp</span></span>
<span class="line"><span>  3_2_doan_ma_tai_lieu.cpp</span></span>
<span class="line"><span>  3_3_tong_luot_muon.cpp</span></span>
<span class="line"><span>  3_4_con_tro_tong_trang.cpp</span></span>
<span class="line"><span>  3_5_sap_xep_ma.cpp</span></span>
<span class="line"><span>  3_6_tim_nhi_phan.cpp</span></span></code></pre></div><p>Nén thư mục thành <code>&lt;MSSV&gt;_&lt;Ho ten khong dau&gt;.zip</code> rồi nộp lên Moodle.</p><h2 id="thang-điem" tabindex="-1">Thang điểm <a class="header-anchor" href="#thang-điem" aria-label="Permalink to &quot;Thang điểm&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nội dung</th><th>Điểm</th></tr></thead><tbody><tr><td>3.1 chạy đúng</td><td>1</td></tr><tr><td>3.2 chạy đúng, có đếm số lần</td><td>1.5</td></tr><tr><td>3.3 có hàm riêng đúng nguyên mẫu</td><td>1.5</td></tr><tr><td>3.4 cấp phát động + truy cập bằng con trỏ + <code>delete[]</code></td><td>2</td></tr><tr><td>3.5 gọi đúng <code>hoanDoi(&amp;a, &amp;b)</code></td><td>2</td></tr><tr><td>3.6 tìm kiếm nhị phân đúng, xử lý cả trường hợp không tìm thấy</td><td>2</td></tr></tbody></table><h2 id="bai-ve-nha" tabindex="-1">Bài về nhà <a class="header-anchor" href="#bai-ve-nha" aria-label="Permalink to &quot;Bài về nhà&quot;">​</a></h2><p>Gộp 3.5 và 3.6 thành <strong>một</strong> chương trình: nhập <code>n</code> mã tài liệu → sắp xếp → in ra → cho phép tra cứu nhiều lần cho tới khi người dùng nhập <code>0</code> để thoát. Hạn nộp: trước buổi tuần 4.</p>`,13))])}const k=s(h,[["render",c]]);export{m as __pageData,k as default};
